head.b:skin:
*{margin:0;padding:0;box-sizing:border-box}

body{background:#0d0f08;overflow:hidden;font-family:monospace;color:#c8bf94;-webkit-user-select:none;user-select:none;touch-action:none}

canvas{display:block}

#tb{position:fixed;top:0;left:0;right:0;height:36px;background:rgba(18,20,10,.93);border-bottom:1px solid #3a3a1e;display:flex;align-items:center;justify-content:space-between;padding:0 6px;font-size:10px;z-index:10}

.tt2{color:#d4a832;font-weight:bold;font-size:11px;letter-spacing:1px}

.sb{color:#8a8060}.sb b{color:#d4a832}.sb2 b{color:#c44040}

#cb{position:fixed;bottom:0;left:0;right:0;background:rgba(18,20,10,.95);border-top:1px solid #3a3a1e;padding:4px;display:flex;flex-wrap:wrap;gap:3px;justify-content:center;align-items:center;z-index:10}

.bt{padding:8px 10px;border:1px solid #4a4a2a;border-radius:3px;background:rgba(40,42,24,.85);color:#c8bf94;font-size:10px;min-width:42px;min-height:36px}

.bt:active{background:rgba(80,82,44,.9);transform:scale(.93)}

.bt.ac{border-color:#d4a832;color:#d4a832}

.bt.dg{border-color:#8a3030;color:#c44040}

.sp{width:1px;height:20px;background:#3a3a1e}

.si{font-size:10px;color:#8a8060;padding:0 3px}.si b{color:#d4a832}

#mw{position:fixed;top:40px;right:3px;z-index:10;border:1px solid #3a3a1e;background:rgba(14,16,8,.9);padding:1px}

#ov{position:fixed;inset:0;background:rgba(10,12,6,.94);display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:50;padding:16px}

#ov.hd{display:none}

#ov h1{color:#d4a832;font-size:20px;letter-spacing:2px;margin-bottom:10px;text-align:center}

#ov p{font-size:11px;color:#8a8060;max-width:280px;text-align:center;line-height:1.5;margin-bottom:6px}

.tk{position:fixed;top:40px;left:50%;transform:translateX(-50%);background:rgba(212,168,50,.14);border:1px solid #d4a832;color:#d4a832;padding:5px 12px;border-radius:3px;font-size:10px;z-index:20;pointer-events:none;white-space:nowrap;animation:ti .3s,to2 .3s 2s forwards}

@keyframes ti{from{opacity:0}to{opacity:1}}

@keyframes to2{to{opacity:0}}



.mpCard{background:rgba(40,42,24,.6);border:1px solid #4a4a2a;border-radius:6px;padding:14px;width:280px;max-width:82vw;display:flex;flex-direction:column;gap:8px;align-items:center;margin:8px 0}
.mpCard h2{font-size:11px;color:#8a8060;letter-spacing:1px;margin:0}
.mpCard input{width:100%;padding:9px;border-radius:4px;border:1px solid #4a4a2a;background:rgba(20,22,12,.9);color:#c8bf94;font-size:13px;text-align:center;font-family:monospace}
.mpAc{border-color:#d4a832 !important;color:#d4a832 !important}
#mpRoomCode{font-size:20px;letter-spacing:4px;color:#d4a832;background:rgba(212,168,50,.1);border:1px solid #d4a832;border-radius:4px;padding:8px 14px}
#mpStatus{font-size:11px;color:#8a8060;text-align:center;min-height:16px;max-width:80vw}
#mpPlayerList{font-size:11px;color:#c8bf94;width:100%;display:flex;flex-direction:column;gap:4px}
.mpPlItem{display:flex;align-items:center;gap:6px;padding:4px 8px;background:rgba(0,0,0,.2);border-radius:3px}
.mpDot{width:8px;height:8px;border-radius:50%;flex-shrink:0}
